async () => {
  const renderer = await import('./src/renderer.js');
  const cases = await import('./src/cases.js');
  const assert = (condition, message) => { if (!condition) throw new Error(message); };
  assert(cases.getCaseForSequence(8), 'Case data must be ready before the fixture');
  const source = cases.getCaseForSequence(8);
  cases.recordRoute(source, source.options.find(option => option.compliance_delta === 3));
  const target = cases.getCaseForSequence(13);
  assert(target.body.includes('merged routing history'), 'Fixture must use the identity-merge return');
  document.getElementById('crt-screen').classList.remove('off');
  document.getElementById('app').style.opacity = '1';
  renderer.clear();
  renderer.setTimingProfile({ charDelay: 0, lineDelay: 0 });
  await renderer.printBlock([
    ['SHIFT 4  ·  CASE 1/4', 'system'],
    ['━'.repeat(60), 'sep'], ['', ''],
    ['CASE REF:  ' + target.ref, 'dim'],
    ['SUBJECT:   ' + target.subject, 'bright'], ['', ''],
    [target.body, ''], ['', '']
  ]);
  const terminal = document.getElementById('terminal');
  const body = [...terminal.querySelectorAll('.line')].find(line => line.textContent.includes('Prior route update:'));
  const lastLineVisible = () => {
    const range = document.createRange();
    range.selectNodeContents(body);
    const end = [...range.getClientRects()].at(-1);
    const bounds = terminal.getBoundingClientRect();
    return end.bottom <= bounds.bottom + 1 && end.top >= bounds.top - 1;
  };
  let routes = 0;
  let continuations = 0;
  for (const count of [1, 2, 3]) {
    renderer.clearOptions();
    terminal.scrollTop = terminal.scrollHeight;
    renderer.showOptions(target.options.slice(0, count), () => { routes++; });
    assert(lastLineVisible(), count + ' routing controls must not clip the last update line');
    assert(Math.abs(terminal.scrollTop - (terminal.scrollHeight - terminal.clientHeight)) <= 1,
      'Control layout must leave the record at its actual bottom');
    terminal.scrollTop = 0;
    await new Promise(resolve => setTimeout(resolve, 150));
    assert(terminal.scrollTop === 0, 'Rereading must not be pulled back to the bottom');
    assert(routes === 0, 'Rereading must not commit a route');
  }
  renderer.clearOptions();
  terminal.scrollTop = terminal.scrollHeight;
  renderer.showContinue('CONTINUE QUEUE', () => { continuations++; });
  assert(lastLineVisible(), 'Continuation control must not clip the final record line');
  terminal.scrollTop = 0;
  await new Promise(resolve => setTimeout(resolve, 150));
  assert(terminal.scrollTop === 0 && continuations === 0,
    'The held record must stay available without an acknowledgement');
  renderer.clear();
  renderer.setTimingProfile();
}
